                     for dr in range(r1 - r0) for dc in range(c1 - c0)
                     if grid[r0 + dr][c0 + dc] != bg
                     and grid[r0 + dr][c0 + dc] not in divider_colors]
            panels.append((ri, ci, r1 - r0, c1 - c0, marks))

    if not panels:
